<?php $statusLabels=['new'=>'جديدة','in_progress'=>'قيد المتابعة','closed'=>'مغلقة'];$emailLabels=['disabled'=>'معطل','pending'=>'في طابور الإرسال','sent'=>'تم إرسال الإشعار','failed'=>'فشل الإشعار','logged'=>'سجل محلي للاختبار']; ?>
<div class="admin-title"><div><h1>رسائل التواصل</h1><p>نجاح الحفظ مستقل عن حالة إشعار البريد.</p></div><a class="text-link" href="/admin/messages">كل الرسائل</a></div>
<?php if($adminRoute==='message'):$message=query('SELECT * FROM contact_messages WHERE id=?',[(int)getstr('id')])->fetch();if(!$message){echo '<div class="notice error">الرسالة غير موجودة.</div>';return;}?><div class="admin-card"><h2>طلب <bdi><?=e($message['reference'])?></bdi></h2><dl class="admin-message-details"><?php foreach(['name'=>'الاسم','email'=>'البريد','company'=>'الشركة','phone'=>'الهاتف','sector_slug'=>'القطاع','locale'=>'اللغة','created_at'=>'التاريخ'] as $key=>$label):?><div><dt><?=$label?></dt><dd dir="auto"><?=e($message[$key]?:'—')?></dd></div><?php endforeach;?></dl><div class="admin-message" dir="auto"><?=e($message['message'])?></div></div><div class="admin-card"><h2>المتابعة</h2><div class="admin-actions"><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="message-status"><input type="hidden" name="id" value="<?=$message['id']?>"><div class="field"><label for="message-status">حالة الرسالة</label><select id="message-status" name="status"><?php foreach($statusLabels as $key=>$label):?><option value="<?=$key?>" <?=$message['status']===$key?'selected':''?>><?=$label?></option><?php endforeach;?></select></div><button class="button">تحديث الحالة</button></form><div><p>إشعار البريد: <strong><?=e($emailLabels[$message['email_status']])?></strong></p><?php if(in_array($message['email_status'],['failed','disabled'])):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="message-retry"><input type="hidden" name="id" value="<?=$message['id']?>"><button class="button button-outline">إعادة جدولة الإشعار</button></form><?php endif;?></div></div></div><form class="admin-card" method="post"><?=csrf_field()?><input type="hidden" name="action" value="delete-message"><input type="hidden" name="id" value="<?=$message['id']?>"><p class="admin-hint">الحذف نهائي من قاعدة بيانات الموقع. لا يشمل نسخ الاستضافة الاحتياطية أو سجلات الإشعار المحلية.</p><label><input type="checkbox" name="confirm" value="yes" required> أؤكد حذف هذه الرسالة نهائياً.</label><button class="danger-button">حذف الرسالة</button></form>
<?php else:$filter=getstr('status');$where=in_array($filter,array_keys($statusLabels),true)?' WHERE status=?':'';$params=$where?[$filter]:[];$page=max(1,(int)getstr('page','1'));$count=(int)query('SELECT COUNT(*) FROM contact_messages'.$where,$params)->fetchColumn();$rows=query('SELECT * FROM contact_messages'.$where.' ORDER BY id DESC LIMIT 30 OFFSET '.(($page-1)*30),$params)->fetchAll();?><nav class="admin-tabs" aria-label="حالة الرسالة"><a href="/admin/messages" <?=$filter===''?'aria-current="page"':''?>>الكل</a><?php foreach($statusLabels as $key=>$label):?><a href="/admin/messages?status=<?=$key?>" <?=$filter===$key?'aria-current="page"':''?>><?=$label?></a><?php endforeach;?></nav><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>الرقم المرجعي</th><th>المرسل</th><th>القطاع</th><th>الحالة</th><th>إشعار البريد</th><th>التاريخ</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><a href="/admin/message?id=<?=$r['id']?>"><bdi><?=e($r['reference'])?></bdi></a></td><td><?=e($r['name'])?><br><span dir="ltr"><?=e($r['email'])?></span></td><td><?=e(record('sectors',$r['sector_slug'],'ar',true)['title']??'عام')?></td><td><?=e($statusLabels[$r['status']])?></td><td><?=e($emailLabels[$r['email_status']])?></td><td dir="ltr"><?=e($r['created_at'])?></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="6">لا توجد رسائل مطابقة.</td></tr><?php endif;?></tbody></table></div><nav class="button-row" aria-label="صفحات الرسائل"><?php if($page>1):?><a class="text-link" href="/admin/messages?status=<?=e($filter)?>&page=<?=$page-1?>">السابق</a><?php endif;if($page*30<$count):?><a class="text-link" href="/admin/messages?status=<?=e($filter)?>&page=<?=$page+1?>">التالي</a><?php endif;?></nav><?php endif;?>
